    $('hotspot-map').innerHTML=svg('미국 본토 0.5도 격자별 2000~2013년 목격 보고 건수 지도',body,920,460);const r=data.regions.find(r=>r.region_id===region),n=e.map.cells.find(c=>c[0]===r.lat_min&&c[1]===r.lon_min)?.[2]||0;
