    for(let h=0;h<24;h++){const angle=h/24*Math.PI*2,[x,y]=pos(angle,125),[x2,y2]=pos(angle,125+values[h]/max*24),[lx,ly]=pos(angle,105);body+=`<path d="M${x} ${y}L${x2} ${y2}" stroke="${h===peak?'#ff5fa2':'#8f63f5'}" stroke-width="8" stroke-linecap="round"><title>${h}시 · ${values[h]}건</title></path>`;if(h%3===0)body+=text(lx,ly+4,String(h).padStart(2,'0'),'text-anchor="middle" style="fill:#38215d"');}
